INSERT INTO activities (id, class_id, title, description, clinical_case_data, deadline) VALUES
('d1000000-0000-0000-0000-000000000001', 'c1000000-0000-0000-0000-000000000001', 'Caso Clínico 01: Rastreamento de Sangramento Oculto em Pós-Operatório Ortopédico', 'Paciente idoso submetido à artroplastia total de quadril, em profilaxia antitrombótica farmacológica com Enoxaparina. Analisar os gatilhos de medicação e cuidados associados à queda súbita nos parâmetros hematológicos.', '{"patientName": "José de Souza Ramos", "age": 68, "gender": "M", "bed": "Leito 204-B - Enfermaria Ortopédica HU-UFS", "admissionDate": "2025-10-02", "patientDays": 8, "admissionNotes": "Paciente admitido para realização eletiva de artroplastia total de quadril direito (ATQ). Hipertenso controlado, sem histórico prévio de coagulopatias. Procedimento cirúrgico realizado sob raquianestesia sem intercorrências imediatas.", "evolutionNotes": [{"dateTime": "2025-10-03 08:30", "professionalRole": "Médico Ortopedista", "note": "1º DPO: Paciente estável, queixa de dor moderada em ferida operatória controlada com dipirona. Dreno de sucção com débito hemático de 120 mL em 12h. Mantida Enoxaparina 40mg SC/dia para tromboprofilaxia."}, {"dateTime": "2025-10-04 14:00", "professionalRole": "Enfermeira Assistencial", "note": "2º DPO: Paciente refere tontura intensa ao tentar sedestação no leito, palidez cutaneomucosa 2+/4+, sudorese fria. PA: 90x55 mmHg, FC: 112 bpm. Curativo operatório com sangramento moderado ativo peridreno. Comunicado ao médico plantonista."}, {"dateTime": "2025-10-04 15:15", "professionalRole": "Médico Plantonista", "note": "Avaliado paciente hipotenso e taquicárdico. Solicitado hemograma de urgência e prova cruzada para 2 concentrados de hemácias. Suspenso uso de Enoxaparina. Iniciada hidratação venosa rápida com Ringer Lactato 1000 mL."}, {"dateTime": "2025-10-04 17:00", "professionalRole": "Enfermeira Assistencial", "note": "Instalada 1ª bolsa de Concentrado de Hemácias (CH) nº 849204. Paciente monitorizado, sem sinais de reação transfusional imediata. PA estabilizada em 110x70 mmHg."}], "prescriptions": [{"medication": "Enoxaparina sódica", "dosage": "40 mg", "route": "Subcutânea", "frequency": "1x ao dia (20h)", "administrationCheck": "Administrado no 1º DPO às 20h. Suspenso no 2º DPO às 15h."}, {"medication": "Dipirona sódica", "dosage": "1 g", "route": "Endovenosa", "frequency": "6/6h se dor", "administrationCheck": "Administrado às 06h e 12h por Enfª Larissa."}, {"medication": "Concentrado de Hemácias", "dosage": "2 unidades", "route": "Endovenosa", "frequency": "Infusão contínua em 2h cada", "administrationCheck": "1ª unidade transfundida às 17h; 2ª unidade às 20h."}], "labExams": [{"examName": "Hemoglobina (Hb) - Admissional", "result": "13.8 g/dL", "referenceValue": "13.0 - 17.5 g/dL", "date": "2025-10-02"}, {"examName": "Hematócrito (Hct) - Admissional", "result": "41.5%", "referenceValue": "40.0 - 50.0%", "date": "2025-10-02"}, {"examName": "Hemoglobina (Hb) - 2º DPO Urgência", "result": "8.1 g/dL (Queda de 41,3%)", "referenceValue": "13.0 - 17.5 g/dL", "date": "2025-10-04"}, {"examName": "Hematócrito (Hct) - 2º DPO Urgência", "result": "24.6%", "referenceValue": "40.0 - 50.0%", "date": "2025-10-04"}, {"examName": "Plaquetas", "result": "185.000 /mm³", "referenceValue": "150.000 - 450.000 /mm³", "date": "2025-10-04"}], "procedures": [{"procedureName": "Artroplastia Total de Quadril Direito", "description": "Colocação de prótese cimentada sem intercorrências técnicas aparentes.", "date": "2025-10-02"}, {"procedureName": "Transfusão de Hemocomponentes", "description": "Transfusão de 2 bolsas de concentrado de hemácias isogrupo isofator sob monitorização.", "date": "2025-10-04"}]}'::jsonb, '2026-04-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000002', 'c1000000-0000-0000-0000-000000000001', 'Caso Clínico 02: Reação de Hipersensibilidade Aguda a Antimicrobiano', 'Investigação de evento adverso a medicamentos em paciente internada para tratamento de pneumonia comunitária que evoluiu com rash maculopapular difuso e prurido após administração de Ceftriaxona.', '{"patientName": "Maria das Graças Conceição", "age": 54, "gender": "F", "bed": "Leito 112-A - Clínica Médica HU-UFS", "admissionDate": "2025-11-01", "patientDays": 6, "admissionNotes": "Paciente admitida com tosse produtiva, febre alta e dispneia leve. Radiografia de tórax evidencia consolidação em lobo inferior direito. Prescrita Ceftriaxona 2g EV 1x/dia.", "evolutionNotes": [{"dateTime": "2025-11-03 10:30", "professionalRole": "Enfermeiro Assistencial", "note": "Durante infusão da 3ª dose de Ceftriaxona, paciente passa a queixar-se de calor súbito no rosto, prurido intenso em tronco e membros superiores. Ao exame: placas eritematosas disseminadas (rash urticariforme). Sem estridor laríngeo ou sibilância. Infusão pausada imediatamente."}, {"dateTime": "2025-11-03 10:45", "professionalRole": "Médico Plantonista", "note": "Avaliada reação anafilactoide moderada secundária a betalactâmico. Prescrita Clemastina (anti-histamínico) 2 mg EV imediata e Hidrocortisona 200 mg EV. Suspensa definitivamente Ceftriaxona da prescrição médica."}, {"dateTime": "2025-11-03 12:00", "professionalRole": "Enfermeiro Assistencial", "note": "Paciente refere melhora substancial do prurido, regressão progressiva das placas eritematosas cutâneas. Sinais vitais: PA 120x80 mmHg, SpO2 97% em ar ambiente. Registro de alergia a cefalosporinas afixado no prontuário e na pulseira de identificação."}], "prescriptions": [{"medication": "Ceftriaxona sódica", "dosage": "2 g", "route": "Endovenosa", "frequency": "1x ao dia (10h)", "administrationCheck": "Interrompida aos 15 min de infusão por reação cutânea aguda."}, {"medication": "Clemastina (anti-histamínico)", "dosage": "2 mg", "route": "Endovenosa", "frequency": "Dose única de emergência", "administrationCheck": "Administrado às 10h50 por Enf. Carlos."}, {"medication": "Hidrocortisona", "dosage": "200 mg", "route": "Endovenosa", "frequency": "Dose única", "administrationCheck": "Administrado às 10h55 por Enf. Carlos."}], "labExams": [{"examName": "Hemograma com Leucograma", "result": "Leucócitos: 11.200/mm³ (Eosinófilos: 7%)", "referenceValue": "4.000 - 10.000 /mm³ (Eos: 1-4%)", "date": "2025-11-03"}], "procedures": []}'::jsonb, '2026-05-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000003', 'c1000000-0000-0000-0000-000000000001', 'Caso Clínico 03: Lesão por Pressão Estágio II em Paciente sob Contenção Mecânica no Leito', 'Auditoria de evento adverso de cuidados: surgimento de lesão por pressão sacral em paciente neurológico acamado submetido a contenção física prolongada por agitação psicomotora.', '{"patientName": "Raimundo Nonato de Jesus", "age": 77, "gender": "M", "bed": "Leito 105-C - Enfermaria de Neurologia HU-UFS", "admissionDate": "2025-11-20", "patientDays": 12, "admissionNotes": "Admitido por sequela motora de Acidente Vascular Cerebral Isquêmico (AVCI), apresentando hemiplegia à esquerda, afasia motora e desorientação temporal.", "evolutionNotes": [{"dateTime": "2025-11-22 22:00", "professionalRole": "Médico Plantonista", "note": "Paciente agitado no leito, com tentativas de retirada da sonda nasoenteral e queda do leito. Prescrito haloperidol e indicada contenção física nos quatro membros para segurança."}, {"dateTime": "2025-11-25 09:00", "professionalRole": "Enfermeira de Pele", "note": "Durante banho no leito e inspeção tegumentar, constatada presença de lesão por pressão em região sacral medindo 3x2 cm, com perda parcial da espessura dérmica, leito eritematoso sem necrose (Estágio II). Histórico de contenção mecânica contínua por 72h com ausência de registro formal de mudança de decúbito no período noturno."}], "prescriptions": [{"medication": "Haloperidol", "dosage": "5 mg", "route": "Intramuscular", "frequency": "Se agitação intensa", "administrationCheck": "Administrado às 22h30 do dia 22/11."}], "labExams": [{"examName": "Albumina sérica", "result": "2.8 g/dL (Hipoproteinemia moderada)", "referenceValue": "3.5 - 5.2 g/dL", "date": "2025-11-21"}], "procedures": [{"procedureName": "Contenção Mecânica no Leito", "description": "Contenção física com ataduras em membros superiores e inferiores por 72 horas.", "date": "2025-11-22"}, {"procedureName": "Curativo com Placa de Hidrocoloide", "description": "Limpeza da lesão sacral com SF 0,9% e aplicação de placa de hidrocoloide estéril.", "date": "2025-11-25"}]}'::jsonb, '2026-06-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000004', 'c1000000-0000-0000-0000-000000000002', 'Caso Clínico 04: Erro de Medicação e Choque Hipoglicêmico Grave por Insulina NPH', 'Análise da cadeia medicamentosa com aplicação de ferramentas da qualidade (Ishikawa e 5W2H) após administração inadvertida de dose triplicada de Insulina NPH.', '{"patientName": "Antônio Fagundes de Oliveira", "age": 61, "gender": "M", "bed": "Leito 302-A - Clínica Médica HU-UFS", "admissionDate": "2025-10-12", "patientDays": 7, "admissionNotes": "Paciente com Diabetes Mellitus tipo 2 descompensado e pé diabético infectado. Prescrita Insulina NPH 14 UI antes do café da manhã.", "evolutionNotes": [{"dateTime": "2025-10-15 07:30", "professionalRole": "Técnico de Enfermagem", "note": "Administrada insulina matinal conforme prescrição médica (leitura ambígua na folha: administradas 40 UI em seringa de 100 UI por confusão de caligrafia com 14 UI)."}, {"dateTime": "2025-10-15 10:45", "professionalRole": "Enfermeira Chefe", "note": "Paciente encontrado desacordado no leito, sudorese profusa e torporoso, sem resposta a chamados verbais. Glicemia capilar de urgência: 32 mg/dL. Acionado time de resposta rápida."}, {"dateTime": "2025-10-15 10:55", "professionalRole": "Médico do Time de Resposta Rápida", "note": "Quadro de hipoglicemia severa neuroglicopênica secundária a sobredose iatrogênica de insulina. Administradas 4 ampolas de Glicose 50% EV em bolus. Paciente recuperou nível de consciência em 15 minutos. Solicitada abertura de notificação de quase-evento e EA grave no NUSP."}], "prescriptions": [{"medication": "Insulina NPH Humana", "dosage": "14 UI (Administradas 40 UI por erro)", "route": "Subcutânea", "frequency": "1x ao dia (07h)", "administrationCheck": "Administrado às 07:30 pelo plantão."}, {"medication": "Glicose Hipertônica 50%", "dosage": "4 ampolas (80 mL)", "route": "Endovenosa", "frequency": "Bolus imediato", "administrationCheck": "Administrado às 10:52 pela equipe do TRR."}], "labExams": [{"examName": "Glicemia Capilar (HGT) - Evento", "result": "32 mg/dL", "referenceValue": "70 - 99 mg/dL", "date": "2025-10-15"}, {"examName": "Glicemia Capilar pós-resgate (15 min)", "result": "118 mg/dL", "referenceValue": "70 - 99 mg/dL", "date": "2025-10-15"}], "procedures": []}'::jsonb, '2026-04-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000005', 'c1000000-0000-0000-0000-000000000002', 'Caso Clínico 05: Superdosagem de Varfarina com Sangramento Ativo e Reversão com Vitamina K', 'Investigação retrospectiva GTT sobre monitoramento de anticoagulação oral em paciente com Fibrilação Atrial crônica que atingiu RNI > 7.0 com hematoma muscular e sangramento gengival.', '{"patientName": "Neuza Barbosa Santos", "age": 70, "gender": "F", "bed": "Leito 210-A - Cardiologia HU-UFS", "admissionDate": "2025-11-05", "patientDays": 10, "admissionNotes": "Paciente em uso contínuo de Varfarina 5mg para profilaxia de tromboembolismo em FA. Internada para tratamento de infecção urinária tratada com ciprofloxacino (potencializador da varfarina).", "evolutionNotes": [{"dateTime": "2025-11-09 11:00", "professionalRole": "Enfermeira Assistencial", "note": "Paciente relata sangramento gengival espontâneo ao escovar os dentes e hematoma volumoso em coxa direita sem trauma relatado. Coletado coagulograma com urgência."}, {"dateTime": "2025-11-09 13:30", "professionalRole": "Médico Hematologista", "note": "RNI laboratorial alarmante de 7.8 (valor alvo 2.0 - 3.0). Risco iminente de hemorragia cerebral ou intracavitária. Indicada suspensão imediata da Varfarina e infusão venosa lenta de Fitomenadiona (Vitamina K1) 10 mg diluída em SF 0,9%."}], "prescriptions": [{"medication": "Varfarina sódica", "dosage": "5 mg", "route": "Via Oral", "frequency": "1x ao dia (18h)", "administrationCheck": "Suspensa imediatamente em 09/11 às 13:30."}, {"medication": "Fitomenadiona (Vitamina K1)", "dosage": "10 mg", "route": "Endovenosa", "frequency": "Dose única em infusão lenta de 30 min", "administrationCheck": "Administrado às 14:00 por Enfª Camila."}], "labExams": [{"examName": "RNI / INR - Admissão", "result": "2.4", "referenceValue": "2.0 - 3.0 (em anticoagulação)", "date": "2025-11-05"}, {"examName": "RNI / INR - Dia do Evento", "result": "7.8 (Gatilho M3)", "referenceValue": "2.0 - 3.0", "date": "2025-11-09"}], "procedures": []}'::jsonb, '2026-05-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000006', 'c1000000-0000-0000-0000-000000000002', 'Caso Clínico 06: Readmissão Precoce em 12 Dias de Paciente Cardiopata Pós-Alta', 'Auditoria de transição do cuidado hospitalar e reconciliação medicamentosa: reinternação precoce de paciente com Insuficiência Cardíaca por orientações incompletas de desmame e dieta no sumário de alta.', '{"patientName": "Manoel Vieira dos Passos", "age": 65, "gender": "M", "bed": "Leito 108-B - Urgência Cardíaca HU-UFS", "admissionDate": "2025-12-02", "patientDays": 6, "admissionNotes": "Paciente com diagnóstico de IC perfil B descompensada. Recebeu alta em 20/11/2025 do mesmo hospital e retorna no 12º dia pós-alta com anasarca e dispneia aos mínimos esforços.", "evolutionNotes": [{"dateTime": "2025-12-02 09:30", "professionalRole": "Médico Emergencista", "note": "Constatada readmissão hospitalar em 12 dias após alta anterior (Gatilho C9). Na anamnese com a família, constatou-se que a receita de alta não especificava a continuidade da furosemida nem a restrição hidrossalina, resultando em sobrecarga volêmica aguda."}], "prescriptions": [{"medication": "Furosemida", "dosage": "40 mg", "route": "Endovenosa", "frequency": "8/8h", "administrationCheck": "Iniciado protocolo de descompensação volêmica."}], "labExams": [{"examName": "BNP (Peptídeo Natriurético Cerebral)", "result": "1.850 pg/mL", "referenceValue": "< 100 pg/mL", "date": "2025-12-02"}], "procedures": []}'::jsonb, '2026-06-30T23:59:59Z'),
('d1000000-0000-0000-0000-000000000007', 'c1000000-0000-0000-0000-000000000003', 'Caso Clínico 07: Pneumonia Associada à Ventilação Mecânica (PAV) e Sepse na UTI Adulto', 'Vigilância epidemiológica e rastreamento GTT no ambiente de terapia intensiva: identificação de infecção do trato respiratório inferior relacionada à assistência à saúde com isolamento de patógeno multirresistente.', '{"patientName": "Severina Santos da Silva", "age": 59, "gender": "F", "bed": "Leito 06 - UTI Adulto HU-UFS", "admissionDate": "2026-03-01", "patientDays": 15, "admissionNotes": "Admitida na UTI após cirurgia de revascularização miocárdica de urgência, em ventilação mecânica invasiva (VMI) via tubo orotraqueal e sedoanalgesia contínua.", "evolutionNotes": [{"dateTime": "2026-03-07 10:00", "professionalRole": "Fisioterapeuta Intensivista", "note": "6º dia de VMI: Piora significativa da mecânica ventilatória, necessidade de elevação de FiO2 de 35% para 60% e PEEP de 8 para 12 cmH2O para manter SpO2 > 92%. Secreção traqueal abundante, purulenta e espessa."}, {"dateTime": "2026-03-07 14:00", "professionalRole": "Médico Intensivista", "note": "Curva febril atingindo 38.9ºC, hipotensão com necessidade de início de Noradrenalina 0.15 mcg/kg/min. Leucocitose importante. Rx de tórax no leito revela infiltrado alveolar novo bilateral. Coletadas hemoculturas e aspirado traqueal quantitativo. Fechado critério clínico para PAV (Gatilhos I1 e C11)."}], "prescriptions": [{"medication": "Meropenem", "dosage": "1 g", "route": "Endovenosa", "frequency": "8/8h em infusão estendida de 3h", "administrationCheck": "Iniciado empiricamente após coleta de culturas."}, {"medication": "Noradrenalina", "dosage": "0.15 mcg/kg/min", "route": "Endovenosa em Bomba de Infusão", "frequency": "Contínua com desmame guiado por PAM > 65", "administrationCheck": "Infusão ativa em cateter venoso central."}], "labExams": [{"examName": "Hemocultura (2 amostras)", "result": "Positiva para Acinetobacter baumannii resistente a carbapenêmicos", "referenceValue": "Negativa", "date": "2026-03-09"}, {"examName": "Procalcitonina sérica", "result": "8.4 ng/mL (Sepse grave)", "referenceValue": "< 0.5 ng/mL", "date": "2026-03-07"}], "procedures": [{"procedureName": "Intubação Orotraqueal e Ventilação Mecânica Invasiva", "description": "TOT nº 7.5 com cuff inflado a 25 cmH2O.", "date": "2026-03-01"}]}'::jsonb, '2026-09-01T23:59:59Z'),
('d1000000-0000-0000-0000-000000000008', 'c1000000-0000-0000-0000-000000000003', 'Caso Clínico 08: Extubação Acidental Não Programada e Parada Respiratória Revertida', 'Rastreamento de evento adverso de gravidade extrema (Categoria H - necessidade de intervenção para manter a vida): falha de fixação do tubo orotraqueal e sedação inadequada com extubação inadvertida.', '{"patientName": "Clóvis Santana dos Reis", "age": 52, "gender": "M", "bed": "Leito 03 - UTI Adulto HU-UFS", "admissionDate": "2026-03-12", "patientDays": 5, "admissionNotes": "Paciente politraumatizado vítima de colisão auto x anteparo fixo, com contusão pulmonar e trauma cranioencefálico moderado.", "evolutionNotes": [{"dateTime": "2026-03-14 03:15", "professionalRole": "Técnico de Enfermagem", "note": "Durante plantão noturno, paciente com despertar súbito e agitação psicomotora vigorosa conseguiu soltar a fixação do tubo com as mãos e removeu completamente o tubo orotraqueal (extubação não programada). Imediatamente acionada equipe médica."}, {"dateTime": "2026-03-14 03:18", "professionalRole": "Médico Intensivista", "note": "Paciente em apneia, cianose labial severa e bradicardia crítica (FC 32 bpm) evoluindo para Parada Cardiorrespiratória em AESP. Iniciadas manobras de RCP, ventilação com ambú com O2 a 100%, administrada 1 ampola de Adrenalina 1 mg EV e procedida reintubação orotraqueal imediata com TOT nº 8.5 com guia metálico. Retorno da circulação espontânea após 3 minutos de RCP (Gatilhos I4, C2 e Severidade H)."}], "prescriptions": [{"medication": "Adrenalina (Epinefrina)", "dosage": "1 mg", "route": "Endovenosa", "frequency": "Bolus imediato na PCR", "administrationCheck": "Administrado às 03h20 por Enf. Beatriz."}, {"medication": "Midazolam + Fentanil", "dosage": "Solução padrão contínua", "route": "Endovenosa em BIC", "frequency": "Ajuste para RASS -4 a -5", "administrationCheck": "Reiniciada infusão às 03h30."}], "labExams": [{"examName": "Gasometria Arterial pós-RCP", "result": "pH: 7.18, pO2: 62 mmHg, pCO2: 58 mmHg, HCO3: 16 mmol/L, Lactato: 4.8 mmol/L", "referenceValue": "pH 7.35-7.45, pO2 80-100", "date": "2026-03-14"}], "procedures": [{"procedureName": "Reintubação Orotraqueal de Emergência", "description": "Laringoscopia direta urgente sob via aérea difícil pós-extubação acidental.", "date": "2026-03-14"}, {"procedureName": "Ressuscitação Cardiopulmonar (RCP)", "description": "1 ciclo de compressões torácicas de alta qualidade e ventilação assistida com RCE.", "date": "2026-03-14"}]}'::jsonb, '2026-12-31T23:59:59Z'),
('d1000000-0000-0000-0000-000000000009', 'c1000000-0000-0000-0000-000000000003', 'Caso Clínico 09: Insuficiência Renal Aguda Nefrotóxica por Vancomicina e Diálise de Urgência', 'Auditoria de dano farmacológico por toxicidade renal: elevação abrupta de creatinina sérica superior a três vezes o valor basal associada a níveis séricos supraterapêuticos de vancomicina.', '{"patientName": "Givaldo Bispo Menezes", "age": 63, "gender": "M", "bed": "Leito 10 - UTI Adulto HU-UFS", "admissionDate": "2026-03-18", "patientDays": 11, "admissionNotes": "Internado por osteomielite de fêmur e sepse secundária. Prescrita Vancomicina 1g EV 12/12h associada a Gentamicina sem realização tempestiva de vancocinemia sérica de controle.", "evolutionNotes": [{"dateTime": "2026-03-24 11:30", "professionalRole": "Médico Nefrologista", "note": "Avaliação renal solicitada por oligúria (diurese 200 mL em 24h). Creatinina sérica saltou de 1.0 mg/dL (basal) para 4.6 mg/dL e ureia para 180 mg/dL. Vancocinemia de vale tóxica em 48 mcg/mL (alvo 15-20 mcg/mL). Diagnosticada Injúria Renal Aguda KDIGO 3 por nefrotoxicidade medicamentosa. Indicada suspensão imediata e implantação de Cateter de Shilley para início de hemodiálise aguda (Gatilhos M5 e C3)."}], "prescriptions": [{"medication": "Vancomicina", "dosage": "1 g", "route": "Endovenosa", "frequency": "12/12h", "administrationCheck": "Suspensa em 24/03 devido a falência renal aguda."}], "labExams": [{"examName": "Creatinina Sérica Basal", "result": "1.0 mg/dL", "referenceValue": "0.7 - 1.3 mg/dL", "date": "2026-03-18"}, {"examName": "Creatinina Sérica - Evento", "result": "4.6 mg/dL (Elevação > 4x basal - Gatilho M5)", "referenceValue": "0.7 - 1.3 mg/dL", "date": "2026-03-24"}, {"examName": "Nível Sérico de Vancomicina (Vale)", "result": "48 mcg/mL (Nível tóxico grave)", "referenceValue": "15 - 20 mcg/mL", "date": "2026-03-24"}], "procedures": [{"procedureName": "Implante de Cateter de Hemodiálise Temporário", "description": "Punção de veia jugular interna direita sob guia ultrassonográfica para inserção de duplo lúmen.", "date": "2026-03-24"}, {"procedureName": "Hemodiálise Aguda Contínua / Intermitente", "description": "Sessão inicial de hemodiálise com ultrafiltração de 1500 mL.", "date": "2026-03-24"}]}'::jsonb, '2026-12-31T23:59:59Z'),
('d1000000-0000-0000-0000-000000000010', 'c1000000-0000-0000-0000-000000000004', 'Caso Clínico 10: Lesão Iatrogênica de Ducto Biliar em Colecistectomia e Conversão Aberta', 'Aplicação do módulo cirúrgico GTT: lesão de órgão adjacente intraoperatória durante videolaparoscopia, mudança de plano cirúrgico e admissão imprevista em UTI pós-operatória.', '{"patientName": "Cláudia Valença de Carvalho", "age": 46, "gender": "F", "bed": "Leito 201-A - Centro Cirúrgico / UTI HU-UFS", "admissionDate": "2026-03-05", "patientDays": 9, "admissionNotes": "Paciente com colelitíase sintomática admitida para colecistectomia videolaparoscópica eletiva.", "evolutionNotes": [{"dateTime": "2026-03-05 16:30", "professionalRole": "Médico Cirurgião Geral", "note": "Durante a dissecção do triângulo de Calot por vídeo, constatada anatomia distorcida por processo inflamatório crônico. Ocorreu secção inadvertida de ducto hepático comum direito com saída biliar ativa abundante. Decidida conversão imediata para laparotomia subcostal direita aberta para reparo biliar com anastomose biliodigestiva em Y de Roux e drenagem de cavidade (Gatilhos S2 e S10)."}, {"dateTime": "2026-03-05 20:00", "professionalRole": "Médico Anestesiologista", "note": "Cirurgia estendida por 5 horas, sangramento estimado em 800 mL. Paciente extubada sob estabilidade, porém necessitando de monitorização intensiva hemodinâmica. Transferida para leito vago na UTI pós-operatória não programado (Gatilho S3)."}], "prescriptions": [{"medication": "Ceftriaxona + Metronidazol", "dosage": "2 g + 500 mg", "route": "Endovenosa", "frequency": "Terapia cirúrgica profilática/terapêutica", "administrationCheck": "Administrado no bloco cirúrgico."}], "labExams": [{"examName": "Bilirrubinas Totais e Frações", "result": "BT: 4.8 mg/dL (Direta: 3.9 mg/dL)", "referenceValue": "BT < 1.2 mg/dL", "date": "2026-03-06"}], "procedures": [{"procedureName": "Conversão Laparoscópica para Laparotomia Aberta", "description": "Mudança não planejada da abordagem cirúrgica decorrente de acidente cirúrgico biliar.", "date": "2026-03-05"}, {"procedureName": "Hepaticojejunostomia em Y de Roux", "description": "Reconstrução do trânsito biliar com dreno de Kehr e dreno tubular.", "date": "2026-03-05"}]}'::jsonb, '2026-09-01T23:59:59Z'),
('d1000000-0000-0000-0000-000000000011', 'c1000000-0000-0000-0000-000000000004', 'Caso Clínico 11: Depressão Respiratória na RPA Revertida com Naloxona', 'Rastreamento GTT de evento adverso pós-anestésico decorrente de sobredose de analgésicos opioides na sala de recuperação pós-anestésica, necessitando de antídoto de emergência.', '{"patientName": "Roberto Menezes Dantas", "age": 55, "gender": "M", "bed": "Leito RPA-04 - Bloco Cirúrgico HU-UFS", "admissionDate": "2026-03-22", "patientDays": 3, "admissionNotes": "Paciente pós-osteossíntese de tíbia sob anestesia geral associada a bloqueio regional.", "evolutionNotes": [{"dateTime": "2026-03-22 15:45", "professionalRole": "Enfermeira da RPA", "note": "Paciente admitido na RPA sonolento. Administrados 10 mg de Morfina fracionada em 30 minutos por queixa de dor intensa. Trinta minutos depois, paciente evoluiu com bradipneia severa (FR 6 irpm), pupilas mióticas puntiformes e SpO2 caindo para 84% em cateter de O2. Acionado médico anestesista de plantão."}, {"dateTime": "2026-03-22 16:00", "professionalRole": "Médico Anestesiologista", "note": "Intoxicação aguda por opioide (depressão respiratória grave). Realizada ventilação assistida por bolsa-válvula-máscara e administrada Naloxona 0.4 mg EV diluída lenta. Em 2 minutos, paciente despertou, FR subiu para 16 irpm e SpO2 atingiu 98% (Gatilhos M9, M11 e Severidade E)."}], "prescriptions": [{"medication": "Morfina Sulfato", "dosage": "10 mg", "route": "Endovenosa", "frequency": "Fracionado na RPA", "administrationCheck": "Administrado às 15:15."}, {"medication": "Cloridrato de Naloxona", "dosage": "0.4 mg", "route": "Endovenosa", "frequency": "Dose de resgate imediata", "administrationCheck": "Administrado às 15:58 por Enfª Gabriela."}], "labExams": [], "procedures": [{"procedureName": "Ventilação sob Pressão Positiva com Máscara Facial", "description": "Suporte ventilatório manual durante reversão farmacológica com antagonista opioide.", "date": "2026-03-22"}]}'::jsonb, '2026-12-31T23:59:59Z'),
('d1000000-0000-0000-0000-000000000012', 'c1000000-0000-0000-0000-000000000004', 'Caso Clínico 12: Análise Longitudinal de Múltiplos EAs e Queda com Dano em Idoso', 'Atividade integradora da metodologia Global Trigger Tool: auditoria integral de prontuário com múltiplos gatilhos encadeados (queda, lesão por pressão e readmissão) e desenho de ciclo PDCA.', '{"patientName": "Eunice Alcantara dos Santos", "age": 82, "gender": "F", "bed": "Leito 101-A - Geriatria HU-UFS", "admissionDate": "2026-03-15", "patientDays": 14, "admissionNotes": "Paciente octogenária frágil admitida para compensação de insuficiência cardíaca e desnutrição calórico-proteica.", "evolutionNotes": [{"dateTime": "2026-03-19 04:30", "professionalRole": "Técnica de Enfermagem", "note": "Paciente levantou do leito desacompanhada para ir ao banheiro e sofreu queda da própria altura com trauma craniano frontal. Grades do leito estavam rebaixadas. Ao exame: hematoma subgaleal volumoso em região frontal e escoriações em cotovelo direito (Gatilho C7)."}, {"dateTime": "2026-03-19 06:00", "professionalRole": "Médico Plantonista", "note": "Avaliação pós-queda: Glasgow 14 (desorientada temporalmente). Solicitada Tomografia Computadorizada de Crânio urgente para descartar hemorragia intracraniana e sutura de ferimento corto-contuso superficial. Prescrita profilaxia antitetânica e repouso absoluto no leito com grades elevadas."}], "prescriptions": [{"medication": "Dipirona sódica", "dosage": "1 g", "route": "Endovenosa", "frequency": "6/6h", "administrationCheck": "Administrado às 06:30."}], "labExams": [{"examName": "Tomografia Computadorizada de Crânio", "result": "Ausência de sangramentos agudos intracranianos ou fraturas ósseas. Hematoma de partes moles extracraniano.", "referenceValue": "Sem alterações agudas", "date": "2026-03-19"}], "procedures": [{"procedureName": "Sutura de Ferimento em Supercílio Direito", "description": "Sutura simples com fio mononylon 5-0 (3 pontos) sob anestesia local.", "date": "2026-03-19"}]}'::jsonb, '2026-12-31T23:59:59Z');
